$(document).on("WebPlayerSeIniciaSistema",function(){var control=Ciel.MPC.WebPlayer.Utilidad.ObtenerControl("PasoTres","TerminosCondiciones");if(!control||!control.DivContenedor){return;}
var divContenedor=control.DivContenedor[0];if(!divContenedor){return;}
var checkBox=divContenedor.querySelector('input[type="checkbox"]');if(!checkBox){return;}
checkBox.addEventListener('change',function(){var validadorCitas=ObtenerValidador();if(!validadorCitas){return;}
validadorCitas.EstablecerCampoCita("ACEPTAPOLITICADATOS",this.checked);});});